/**
 * Turning the nested changes of embed fields into embedded rows: for `applyChanges`,
 * `getField`, and the repo, which writes the whole column.
 *
 * A child changeset of an embed becomes a row of the embedded schema, built by its row
 * factory (no constructor runs): its changes over its data, or for a new item its changes
 * over the fields' defaults, with autogenerated values (a key `t.uuid().primaryKey()
 * .autogenerate()`, timestamps) filled in. Children whose action is `"delete"` are left
 * out of a list.
 *
 * @module
 */
import type { ChangesetError } from "../../contracts/changeset.js";
import type { AnySchema, FieldMeta, RowState, SchemaMeta } from "../../contracts/schema.js";
import { meta } from "../../schema/schema.js";
import { embedTypeInfo } from "../../types/embed.js";
import { Changeset, fieldsOf, rebuild } from "../changeset.js";
import type { AnyChangeset, Values } from "./relation.js";

const hasOwn = Object.hasOwn;

/** Whether `value` is a nested change of an embed: a changeset, or a list holding them. */
export function isNestedValue(value: unknown): boolean {
  if (value instanceof Changeset) return true;
  if (!Array.isArray(value)) return false;
  for (const item of value) if (item instanceof Changeset) return true;
  return false;
}

/**
 * The value of an embed field for a change: `null`, a row, or a list of rows. A value
 * that is not a nested change is returned as it is.
 *
 * @example
 * ```ts
 * const address = embedValue(cs.changes.address, "built"); // an Address row
 * ```
 */
export function embedValue(value: unknown, state: RowState): unknown {
  if (value instanceof Changeset) return embeddedRow(value as AnyChangeset, state);
  if (!Array.isArray(value) || !isNestedValue(value)) return value;
  const out: unknown[] = [];
  for (const item of value) {
    if (item instanceof Changeset) {
      if ((item as AnyChangeset).action !== "delete") out.push(embeddedRow(item as AnyChangeset, state));
    } else out.push(item);
  }
  return out;
}

function initialValue(field: FieldMeta): unknown {
  const fallback = field.default;
  if (fallback !== undefined) return fallback.kind === "value" ? fallback.value : fallback.fn();
  return field.nullable ? null : undefined;
}

/** Whether a changeset has a change. */
function hasChanges(changeset: AnyChangeset): boolean {
  for (const key in changeset.changes as Values) if (hasOwn(changeset.changes, key)) return true;
  return false;
}

/** A child changeset of an embed as a row of the embedded schema. */
function embeddedRow(child: AnyChangeset, state: RowState): object {
  const data = child.data as Values | null;
  if (data !== null && !hasChanges(child)) return data;
  const schemaMeta = meta(child.model as AnySchema);
  const changes = child.changes as Values;
  const values: unknown[] = [];
  let stamp: unknown;
  for (const field of schemaMeta.persisted) {
    let value: unknown;
    if (hasOwn(changes, field.name)) value = embedValue(changes[field.name], state);
    else if (data !== null) {
      value = data[field.name];
      if (field.autogenerate?.on === "insertAndUpdate") value = generated(field, stamp);
    } else if (field.default === undefined && field.autogenerate !== undefined) {
      value = generated(field, stamp);
    } else {
      value = initialValue(field);
    }
    if (field.autogenerate !== undefined && value instanceof Date) stamp ??= value;
    values.push(value);
  }
  const out = schemaMeta.create(values, schemaMeta.rowMeta(state, undefined)) as Record<string, unknown>;
  for (const field of schemaMeta.fields) {
    if (!field.virtual) continue;
    if (hasOwn(changes, field.name)) out[field.name] = changes[field.name];
    else if (data !== null) out[field.name] = data[field.name];
  }
  return out;
}

/** A generated value; timestamps of one row share the first one made. */
function generated(field: FieldMeta, stamp: unknown): unknown {
  const value = (field.autogenerate as NonNullable<FieldMeta["autogenerate"]>).fn();
  return stamp instanceof Date && value instanceof Date ? stamp : value;
}

const BLANK: ChangesetError = Object.freeze({
  message: "can't be blank",
  validation: "required",
  meta: Object.freeze({}),
});

/**
 * The parent with `can't be blank` on every new embedded item (at any depth) that would
 * have no value for a field that is neither nullable nor defaulted; `undefined` when
 * there is none. The repo checks this before it writes a parent, as it checks the
 * parent's own fields.
 *
 * @example
 * ```ts
 * const failed = missingEmbedded(prepared);
 * if (failed !== undefined) return failure(failed);
 * ```
 */
export function missingEmbedded(changeset: AnyChangeset): AnyChangeset | undefined {
  const changes = changeset.changes as Values;
  let next: Record<string, unknown> | undefined;
  for (const field of fieldsOf(changeset).values()) {
    if (embedTypeInfo(field.type) === undefined || !hasOwn(changes, field.name)) continue;
    const value = changes[field.name];
    if (value instanceof Changeset) {
      const checked = checkChild(value as AnyChangeset);
      if (checked !== undefined) {
        next ??= { ...changes };
        next[field.name] = checked;
      }
    } else if (Array.isArray(value)) {
      let list: unknown[] | undefined;
      value.forEach((item, i) => {
        if (!(item instanceof Changeset) || (item as AnyChangeset).action === "delete") return;
        const checked = checkChild(item as AnyChangeset);
        if (checked === undefined) return;
        list ??= value.slice();
        list[i] = checked;
      });
      if (list !== undefined) {
        next ??= { ...changes };
        next[field.name] = list;
      }
    }
  }
  return next === undefined ? undefined : rebuild(changeset, { changes: next, valid: false });
}

/** A child with its own missing fields and its embeds' marked, or `undefined` when nothing is missing. */
function checkChild(child: AnyChangeset): AnyChangeset | undefined {
  let out = missingEmbedded(child);
  const base = out ?? child;
  const schemaMeta: SchemaMeta = meta(base.model as AnySchema);
  const changes = base.changes as Values;
  const data = base.data as Values | null;
  let errors = base.errors;
  for (const field of schemaMeta.persisted) {
    if (field.nullable || hasOwn(changes, field.name)) continue;
    if (data === null && field.autogenerate !== undefined) continue;
    const value = data !== null ? data[field.name] : initialValue(field);
    if (value === undefined || value === null) {
      errors = { ...errors, [field.name]: [...(errors[field.name] ?? []), BLANK] };
    }
  }
  if (errors !== base.errors) out = rebuild(base, { errors, valid: false });
  return out;
}

/**
 * The changes of a changeset with every nested change of an embed field turned into
 * rows (`changes` itself when there is none).
 *
 * @example
 * ```ts
 * const values = embedChanges(prepared, "loaded").address; // an Address row
 * ```
 */
export function embedChanges(changeset: AnyChangeset, state: RowState): Values {
  const changes = changeset.changes as Values;
  let out: Record<string, unknown> | undefined;
  for (const key in changes) {
    if (!hasOwn(changes, key)) continue;
    const value = changes[key];
    if (!isNestedValue(value)) continue;
    const field = fieldsOf(changeset).get(key);
    if (field === undefined || embedTypeInfo(field.type) === undefined) continue;
    out ??= { ...changes };
    out[key] = embedValue(value, state);
  }
  return out ?? changes;
}
